// One item: every hotel on the shortlist whose stay total fell by at least DROP_PCT since the last run, as a ready-to-send email body.
const DROP_PCT = 3;                          // report a hotel when it is this many percent cheaper than last time
const MAX_KEYS = 5000;                       // hotel_id|check_in keys remembered between runs (oldest dropped)
const store = $getWorkflowStaticData('global');
store.prices = store.prices || {};
const rows = $input.all().map(i => i.json);
const hotels = rows.filter(r => r.type === 'hotel' && r.hotel_id);
const today = new Date().toISOString().slice(0, 10);
const drops = [], sold_out = [];
let priced = 0, first_seen = 0;
for (const h of hotels) {
  if (h.sold_out || h.price_total == null) { sold_out.push(h.name || String(h.hotel_id)); continue; }   // sold out = delivered free by the actor
  priced++;
  const key = `${h.hotel_id}|${h.check_in}`;
  const prev = store.prices[key];
  const change_pct = prev && prev.price ? Math.round((h.price_total - prev.price) / prev.price * 1000) / 10 : null;
  if (change_pct === null) first_seen++;
  else if (change_pct <= -DROP_PCT) drops.push({
    hotel_id: h.hotel_id, name: h.name || String(h.hotel_id), url: h.url || '',
    check_in: h.check_in, check_out: h.check_out, nights: h.nights, currency: h.currency,
    was: prev.price, now: Math.round(h.price_total * 100) / 100,
    was_display: prev.display || String(prev.price), now_display: h.price_display || String(h.price_total),
    nightly: h.price_nightly, change_pct, saving: Math.round((prev.price - h.price_total) * 100) / 100,
    free_cancellation: !!h.free_cancellation, breakfast_included: !!h.breakfast_included, room_name: h.room_name || '',
  });
  store.prices[key] = { price: h.price_total, display: h.price_display || '', checked_on: today };
}
const keys = Object.keys(store.prices);
if (keys.length > MAX_KEYS) for (const k of keys.slice(0, keys.length - MAX_KEYS)) delete store.prices[k];
const stay = hotels.length ? `${hotels[0].check_in} → ${hotels[0].check_out} (${hotels[0].nights} night${hotels[0].nights > 1 ? 's' : ''})` : '';
const counted = `${priced} of ${hotels.length} properties had a price; ${sold_out.length} sold out (sold-out properties are delivered free).`;
if (!drops.length) return [{ json: { none: true, count: 0, checked: hotels.length, priced, sold_out: sold_out.length, first_seen, stay, checked_on: today, note: counted } }];
drops.sort((a, b) => a.change_pct - b.change_pct);
const pad = (s, n) => String(s).length >= n ? String(s).slice(0, n - 1) + ' ' : String(s) + ' '.repeat(n - String(s).length);
const table = [`${pad('Hotel', 34)}${pad('was', 12)}${pad('now', 12)}change`,
  ...drops.map(d => `${pad(d.name, 34)}${pad(d.was_display, 12)}${pad(d.now_display, 12)}${d.change_pct}%`)].join('\n');
const body = [`${drops.length} price drop${drops.length > 1 ? 's' : ''} on your shortlist for ${stay}:`, '', table, '',
  ...drops.map(d => `${d.name} — ${d.now_display} for the stay (${d.nightly} ${d.currency}/night), was ${d.was_display}: you save ${d.saving} ${d.currency}${d.free_cancellation ? ', free cancellation' : ''}${d.breakfast_included ? ', breakfast included' : ''}\n${d.url}`),
  '', counted].join('\n');
return [{ json: { count: drops.length, stay, checked: hotels.length, priced, sold_out: sold_out.length, sold_out_names: sold_out, first_seen, checked_on: today,
  subject: `Price drop: ${drops[0].name} ${drops[0].change_pct}% for ${drops[0].check_in}`, table, body, drops } }];
